import Axis from '../../../../src/coord/Axis';
import OrdinalScale from '../../../../src/scale/Ordinal';
import Model from '../../../../src/model/Model';
import { AxisBaseModel } from '../../../../src/coord/AxisBaseModel';

/**
 * Make a category axis on band, of which the coord extent is `[0, 300]`.
 */
function createBandAxis(): Axis {
    const scale = new OrdinalScale({
        ordinalMeta: ['a', 'b', 'c', 'd', 'e']
    });
    const axis = new Axis('x', scale, [0, 300]);
    axis.type = 'category';
    axis.onBand = true;
    axis.model = new Model({
        type: 'category',
        axisLabel: {},
        // Display every category.
        axisTick: { show: true, interval: 0 }
    }) as unknown as AxisBaseModel;
    return axis;
}

function coordsOf(axis: Axis, clamp?: boolean): number[] {
    return axis.getTicksCoords({ clamp: clamp }).map(item => item.coord);
}

describe('axis_ticksInsideExtent', function () {

    it('should keep band ticks inside the axis extent', function () {
        const axis = createBandAxis();

        // All the categories are displayed.
        expect(coordsOf(axis)).toEqual([0, 60, 120, 180, 240, 300]);

        // Narrow the window down (like dataZoom does), while the ticks
        // that were made for the previous window are still there.
        axis.scale.setExtent(2, 4);

        const coords = axis.getTicksCoords();
        const extent = axis.getExtent();
        coords.forEach(function (item) {
            expect(item.coord).toBeGreaterThanOrEqual(extent[0]);
            expect(item.coord).toBeLessThanOrEqual(extent[1]);
        });
        expect(coords.map(item => item.coord)).toEqual([0, 100, 200, 300]);
    });

    it('should clamp band ticks to the axis extent when clamp is specified', function () {
        const axis = createBandAxis();

        expect(coordsOf(axis, true)).toEqual([0, 60, 120, 180, 240, 300]);

        axis.scale.setExtent(2, 4);

        const extent = axis.getExtent();
        const coords = coordsOf(axis, true);
        coords.forEach(function (coord) {
            expect(coord).toBeGreaterThanOrEqual(extent[0]);
            expect(coord).toBeLessThanOrEqual(extent[1]);
        });
        // The extent bounds are always included when clamp is specified.
        expect(coords[0]).toBe(extent[0]);
        expect(coords[coords.length - 1]).toBe(extent[1]);
    });

    it('should not overflow the grid when dataZoom is used', function () {
        const chart: EChartsType = createChart({ width: 400, height: 300 });
        const categories: string[] = [];
        const values: number[] = [];
        for (let i = 0; i < 20; i++) {
            categories.push('cat' + i);
            values.push(i % 7 + 1);
        }
        chart.setOption({
            xAxis: { type: 'category', data: categories },
            yAxis: {},
            dataZoom: [{ type: 'inside', start: 0, end: 100 }],
            series: [{ type: 'bar', data: values }]
        } as EChartsOption);

        function checkTicksInsideGrid() {
            const axisModel = getECModel(chart).getComponent('xAxis', 0) as CartesianAxisModel;
            const axis = axisModel.axis;
            const extent = axis.getExtent();
            const ticksCoords = axis.getTicksCoords();
            expect(ticksCoords.length).toBeGreaterThan(1);
            ticksCoords.forEach(function (item) {
                // Tolerance for the rounding error of the coord calculation.
                expect(item.coord).toBeGreaterThanOrEqual(extent[0] - 1e-8);
                expect(item.coord).toBeLessThanOrEqual(extent[1] + 1e-8);
            });
            // The band ticks always cover the whole axis.
            expect(ticksCoords[0].coord).toBeCloseTo(extent[0], 6);
            expect(ticksCoords[ticksCoords.length - 1].coord).toBeCloseTo(extent[1], 6);
        }

        checkTicksInsideGrid();

        chart.dispatchAction({ type: 'dataZoom', start: 23, end: 61 });
        checkTicksInsideGrid();

        chart.dispatchAction({ type: 'dataZoom', start: 71, end: 100 });
        checkTicksInsideGrid();

        chart.dispose();
    });

});

