```ts
// Apache license header (copy from test/ut/spec/coord/axisCustomValues.test.ts)
import { createChart, getECModel, getViewGroup } from '../../../core/utHelper';
import { EChartsType } from '@/src/echarts';
import { EChartsOption } from '@/src/export/option';
import CartesianAxisModel from '@/src/coord/cartesian/AxisModel';
import Axis from '@/src/coord/Axis';
import IntervalScale from '@/src/scale/Interval';
import Model from '@/src/model/Model';
import Path from 'zrender/src/graphic/Path';
import Element from 'zrender/src/Element';
import { makeSplitLineBoundaryFilter } from '@/src/component/axis/axisSplitHelper';

// --- helpers ---
// Cartesian split lines are individual `graphic.Line`s: `anid` is
// `'line_' + tickValue`, or null for the extra on-band boundary entry.
// The axis line has anid 'line', ticks 'tick_*', minor split lines
// 'minor_line_*', labels 'label_*', split areas are Rects.
function getSplitLineEls(chart: EChartsType, mainType: string, index?: number): Element[] {
    const out: Element[] = [];
    getViewGroup(chart, mainType as any, index).traverse(function (el: Element) {
        if (el.type === 'line' && (el.anid == null || el.anid.indexOf('line_') === 0)) {
            out.push(el);
        }
    });
    return out;
}
function getAnidsWithPrefix(chart: EChartsType, mainType: string, prefix: string): string[] { /* traverse, collect el.anid starting with prefix */ }
// Single-axis and polar split lines are merged into one Path bundle per color
// (`graphic.mergePath`); count the path commands instead of elements.
function getMergedPathLen(chart: EChartsType, mainType: string, index?: number): number {
    let len = 0;
    getViewGroup(chart, mainType as any, index).traverse(function (el: Element) {
        if (el.type === 'path') { len += (el as Path).getUpdatedPathProxy(true).len(); }
    });
    return len;
}
```

Cases:

A. `describe('splitLine_boundaryFilter')` — pure unit tests of the helper, no chart:
  - `new Axis('y', new IntervalScale(), [0, 300])` + `new Model({}) as any` -> filter returns false for 0, 150 and 300 (defaults absent => nothing hidden).
  - `new Model({ showMinLine: false })` -> true at 0, false at 150 and 300.
  - `new Model({ showMaxLine: false })` -> true at 300 only.
  - both false -> true at 0 and 300, false at 150.
  - INVERSE: build the axis with an already-swapped extent `[300, 0]` (what `Grid#adjustAxes` does) and `{ showMinLine: false }` -> hidden at coord 300, not at 0. This is the regression guard proving min/max follow the data, not the pixel order.
  - float tolerance: `{ showMaxLine: false }` -> hidden at `300 - 1e-9`.

B. `describe('splitLine_showMinMaxLine_cartesian')` with `chart = createChart({ width: 500, height: 400 })` and a value yAxis (`yAxis: { type: 'value', min: 0, max: 100, splitLine: { show: true } }`, `xAxis: { type: 'category', data: [...] }`, one bar series, `animation: false`):
  - baseline: `getSplitLineEls(chart, 'yAxis', 0).length` === `axisModel.axis.getTicksCoords({ tickModel: axisModel.getModel('splitLine') }).length`, and the anid set contains `'line_0'` and `'line_100'`.
  - explicit `showMinLine: true, showMaxLine: true` gives the identical anid list (acceptance: unchanged when absent).
  - `showMinLine: false` -> length is baseline-1 and `'line_0'` is absent while `'line_100'` is present.
  - `showMaxLine: false` -> baseline-1, `'line_100'` absent, `'line_0'` present.
  - both false -> baseline-2, neither present, all interior tickValues still present.
  - `inverse: true` + `showMinLine: false` -> the missing anid is still `'line_0'` (the data min), and the remaining lines' `shape.y1` set proves the max line at the top edge is still drawn.
  - category xAxis with `boundaryGap: true` and `splitLine: { show: true, showMinLine: false }`: the on-band boundary entries have `anid == null`, so assert on geometry — with defaults `Math.min(...xs) === gridRect.x` and `Math.max(...xs) === gridRect.x + gridRect.width` (use `toBeCloseTo`, sub-pixel optimization shifts by <=0.5), and with `showMinLine: false` `Math.min(...xs) > gridRect.x + 1`. Get `gridRect` from `getECModel(chart).getComponent('grid', 0).coordinateSystem.getRect()`.
  - non-boundary guard: `yAxis: { min: 0, max: 100, splitLine: { show: true, interval: (i) => i > 0, showMinLine: false } }` (or `axisTick.customValues`) — when no tick sits on the extent, `showMinLine: false` removes nothing.

C. `describe('splitLine_showMinMaxLine_notAffectOthers')` on the same cartesian chart with `minorTick: { show: true }`, `minorSplitLine: { show: true }`, `splitArea: { show: true }`:
  - `getAnidsWithPrefix(chart, 'yAxis', 'minor_line_').length` is identical with and without `showMinLine/showMaxLine: false`.
  - `getAnidsWithPrefix(chart, 'yAxis', 'area_').length` is identical too (splitArea geometry must not change).

D. `describe('splitLine_showMinMaxLine_singleAxis')` — `singleAxis: { type: 'value', min: 0, max: 100, splitLine: { show: true } }` + a themeRiver/scatter series on `singleAxis`; `getMergedPathLen(chart, 'singleAxis', 0)` for defaults > for `showMinLine: false` > for both false. Extra precise check: grab the single `type === 'path'` child and compare `el.getBoundingRect()` (in the group's local space) with `axisModel.coordinateSystem.getRect()` — with defaults `rect.x` is at `gridRect.x`, with `showMinLine: false` it is strictly greater.

E. `describe('splitLine_showMinMaxLine_polar')` — `polar: {}`, `radiusAxis: { type: 'value', min: 0, max: 100, splitLine: { show: true }, axisTick: { show: false }, axisLabel: { show: false } }`, `angleAxis: { type: 'value', startAngle: 0, endAngle: 180, splitLine: { show: true }, axisTick: { show: false }, axisLabel: { show: false } }`, one polar line series. Disabling `axisTick` matters because `AngleAxisView#axisTick` also emits a `mergePath` bundle (`type === 'path'`).
  - radiusAxis: `getMergedPathLen(chart, 'radiusAxis', 0)` for defaults > for `showMaxLine: false`; also the bundle's `getBoundingRect().width` shrinks below `2 * radiusExtent[1]` when the outer circle is hidden.
  - angleAxis (180 degree extent): defaults > `showMinLine: false` > ... and both-false is the smallest.
  - full-circle angleAxis (`startAngle: 90` default, no `endAngle`) with `showMaxLine: false`: length is unchanged (the boundary tick was already deduplicated by `fixAngleOverlap`), while `showMinLine: false` shrinks it — encode this as the documented behavior.

